import React, { useRef, useState, useEffect, useCallback } from 'react';

const COLORS = [
  '#d0b0ff','#f9a8c9','#7ecfc0','#f0c060','#e07070','#8ab8e8',
  '#ffffff','#b8a8d4','#5a3a8a','#2a1e42','#0a0814','#f0e8d0',
  '#7b3fff','#3fff7b','#ff7b3f','#3f7bff','#ff3f7b','#7bff3f',
];

const BRUSHES = [
  { id: 'pen', label: 'Pen', icon: 'ti-pencil' },
  { id: 'brush', label: 'Brush', icon: 'ti-brush' },
  { id: 'marker', label: 'Marker', icon: 'ti-highlight' },
  { id: 'spray', label: 'Spray', icon: 'ti-droplet' },
  { id: 'eraser', label: 'Eraser', icon: 'ti-eraser' },
  { id: 'fill', label: 'Fill', icon: 'ti-paint-filled' },
  { id: 'line', label: 'Line', icon: 'ti-minus' },
  { id: 'rect', label: 'Rect', icon: 'ti-square' },
  { id: 'circle', label: 'Circle', icon: 'ti-circle' },
];

const SIZES = [2, 4, 8, 14, 22, 35];

const FILTERS = [
  { id: 'none', label: 'None' },
  { id: 'grayscale', label: 'Grayscale' },
  { id: 'sepia', label: 'Sepia' },
  { id: 'invert', label: 'Invert' },
  { id: 'blur', label: 'Blur' },
  { id: 'saturate', label: 'Vivid' },
];

const STICKERS = ['⭐','🌙','✨','🔥','💜','🖤','🌸','⚡','🎴','🗡️','👁️','🌑','💫','🦋','🌿','🎵'];

export default function SketchPad() {
  const canvasRef = useRef(null);
  const overlayRef = useRef(null);
  const containerRef = useRef(null);
  const [brush, setBrush] = useState('pen');
  const [color, setColor] = useState('#d0b0ff');
  const [size, setSize] = useState(4);
  const [opacity, setOpacity] = useState(1);
  const [history, setHistory] = useState([]);
  const [redoStack, setRedoStack] = useState([]);
  const [drawing, setDrawing] = useState(false);
  const [startPos, setStartPos] = useState(null);
  const [layer, setLayer] = useState(0);
  const [layers, setLayers] = useState([
    { id: 0, name: 'Layer 1', visible: true, opacity: 1 },
  ]);
  const [showLayers, setShowLayers] = useState(false);
  const [showStickers, setShowStickers] = useState(false);
  const [filter, setFilter] = useState('none');
  const [customColor, setCustomColor] = useState('#d0b0ff');
  const [showGrid, setShowGrid] = useState(false);
  const [symmetry, setSymmetry] = useState(false);
  const [zoom, setZoom] = useState(1);
  const [canvasSize, setCanvasSize] = useState({ w: 800, h: 600 });
  const drawRef = useRef({ drawing: false, lx: 0, ly: 0, startX: 0, startY: 0 });
  const canvasCtxRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = canvasSize.w * dpr;
    canvas.height = canvasSize.h * dpr;
    canvas.style.width = canvasSize.w + 'px';
    canvas.style.height = canvasSize.h + 'px';
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.fillStyle = '#080810';
    ctx.fillRect(0, 0, canvasSize.w, canvasSize.h);
    canvasCtxRef.current = ctx;
    saveHistory();
  }, []);

  const saveHistory = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const data = canvas.toDataURL();
    setHistory(h => [...h.slice(-30), data]);
    setRedoStack([]);
  }, []);

  const getPos = (e) => {
    const canvas = canvasRef.current;
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvasSize.w / rect.width;
    const scaleY = canvasSize.h / rect.height;
    const src = e.touches ? e.touches[0] : e;
    return {
      x: (src.clientX - rect.left) * scaleX,
      y: (src.clientY - rect.top) * scaleY,
    };
  };

  const applyBrush = (ctx, x, y, px, py) => {
    ctx.globalAlpha = opacity;
    ctx.strokeStyle = brush === 'eraser' ? '#080810' : color;
    ctx.fillStyle = color;
    ctx.lineWidth = size;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (brush === 'pen') {
      ctx.globalCompositeOperation = 'source-over';
      ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(x, y); ctx.stroke();
    } else if (brush === 'brush') {
      ctx.globalCompositeOperation = 'source-over';
      ctx.lineWidth = size * 2;
      ctx.globalAlpha = opacity * 0.4;
      for (let i = 0; i < 3; i++) {
        const jx = x + (Math.random() - 0.5) * size * 0.5;
        const jy = y + (Math.random() - 0.5) * size * 0.5;
        ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(jx, jy); ctx.stroke();
      }
    } else if (brush === 'marker') {
      ctx.globalCompositeOperation = 'multiply';
      ctx.globalAlpha = 0.6;
      ctx.lineWidth = size * 3;
      ctx.lineCap = 'square';
      ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(x, y); ctx.stroke();
    } else if (brush === 'spray') {
      ctx.globalCompositeOperation = 'source-over';
      const density = size * 3;
      for (let i = 0; i < density; i++) {
        const angle = Math.random() * Math.PI * 2;
        const radius = Math.random() * size * 2;
        const sx = x + radius * Math.cos(angle);
        const sy = y + radius * Math.sin(angle);
        ctx.globalAlpha = Math.random() * opacity * 0.6;
        ctx.fillRect(sx, sy, 1.5, 1.5);
      }
    } else if (brush === 'eraser') {
      ctx.globalCompositeOperation = 'source-over';
      ctx.globalAlpha = 1;
      ctx.lineWidth = size * 3;
      ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(x, y); ctx.stroke();
    }
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;

    if (symmetry) {
      const mx = canvasSize.w - x;
      ctx.globalAlpha = opacity;
      ctx.strokeStyle = brush === 'eraser' ? '#080810' : color;
      ctx.lineWidth = size;
      ctx.beginPath();
      ctx.moveTo(canvasSize.w - px, py);
      ctx.lineTo(mx, y);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
  };

  const floodFill = (startX, startY) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;
    const px = Math.floor(startX * dpr);
    const py = Math.floor(startY * dpr);
    const w = canvas.width;
    const idx = (py * w + px) * 4;
    const targetR = data[idx], targetG = data[idx+1], targetB = data[idx+2];
    const fillR = parseInt(color.slice(1,3),16);
    const fillG = parseInt(color.slice(3,5),16);
    const fillB = parseInt(color.slice(5,7),16);
    if (targetR===fillR && targetG===fillG && targetB===fillB) return;
    const stack = [[px, py]];
    const visited = new Set();
    const key = (x,y) => y*w+x;
    const matches = (i) => Math.abs(data[i]-targetR)<30 && Math.abs(data[i+1]-targetG)<30 && Math.abs(data[i+2]-targetB)<30;
    while (stack.length) {
      const [cx, cy] = stack.pop();
      if (cx<0||cx>=w||cy<0||cy>=canvas.height) continue;
      const k = key(cx,cy);
      if (visited.has(k)) continue;
      const i = (cy*w+cx)*4;
      if (!matches(i)) continue;
      visited.add(k);
      data[i]=fillR; data[i+1]=fillG; data[i+2]=fillB; data[i+3]=255;
      stack.push([cx+1,cy],[cx-1,cy],[cx,cy+1],[cx,cy-1]);
    }
    ctx.putImageData(imageData, 0, 0);
    saveHistory();
  };

  const startDraw = (e) => {
    if (e.touches) e.preventDefault();
    const { x, y } = getPos(e);
    const d = drawRef.current;
    d.drawing = true; d.lx = x; d.ly = y; d.startX = x; d.startY = y;
    setDrawing(true);
    setStartPos({ x, y });
    if (brush === 'fill') { floodFill(x, y); d.drawing = false; setDrawing(false); return; }
    if (brush === 'pen' || brush === 'brush' || brush === 'marker' || brush === 'spray' || brush === 'eraser') {
      const ctx = canvasRef.current.getContext('2d');
      applyBrush(ctx, x, y, x, y);
    }
  };

  const continueDraw = (e) => {
    if (e.touches) e.preventDefault();
    const d = drawRef.current;
    if (!d.drawing) return;
    const { x, y } = getPos(e);
    const ctx = canvasRef.current.getContext('2d');

    if (['line','rect','circle'].includes(brush)) {
      // Draw on overlay
      const ov = overlayRef.current;
      if (!ov) return;
      const oct = ov.getContext('2d');
      oct.clearRect(0, 0, ov.width, ov.height);
      oct.strokeStyle = color;
      oct.lineWidth = size;
      oct.globalAlpha = opacity;
      oct.lineCap = 'round';
      if (brush === 'line') {
        oct.beginPath(); oct.moveTo(d.startX, d.startY); oct.lineTo(x, y); oct.stroke();
      } else if (brush === 'rect') {
        oct.strokeRect(d.startX, d.startY, x - d.startX, y - d.startY);
      } else if (brush === 'circle') {
        const rx = Math.abs(x - d.startX) / 2, ry = Math.abs(y - d.startY) / 2;
        const cx = d.startX + (x - d.startX) / 2, cy = d.startY + (y - d.startY) / 2;
        oct.beginPath(); oct.ellipse(cx, cy, rx, ry, 0, 0, Math.PI*2); oct.stroke();
      }
    } else {
      applyBrush(ctx, x, y, d.lx, d.ly);
    }
    d.lx = x; d.ly = y;
  };

  const endDraw = (e) => {
    const d = drawRef.current;
    if (!d.drawing) return;
    d.drawing = false;
    setDrawing(false);

    if (['line','rect','circle'].includes(brush)) {
      const ov = overlayRef.current;
      const ctx = canvasRef.current.getContext('2d');
      ctx.drawImage(ov, 0, 0, canvasSize.w, canvasSize.h);
      const oct = ov.getContext('2d');
      oct.clearRect(0, 0, ov.width, ov.height);
    }
    saveHistory();
  };

  const undo = () => {
    if (history.length < 2) return;
    const newHist = [...history];
    const current = newHist.pop();
    setRedoStack(r => [...r, current]);
    setHistory(newHist);
    const img = new Image();
    img.onload = () => {
      const ctx = canvasRef.current.getContext('2d');
      ctx.clearRect(0, 0, canvasSize.w, canvasSize.h);
      ctx.drawImage(img, 0, 0, canvasSize.w, canvasSize.h);
    };
    img.src = newHist[newHist.length - 1];
  };

  const redo = () => {
    if (!redoStack.length) return;
    const newRedo = [...redoStack];
    const next = newRedo.pop();
    setRedoStack(newRedo);
    setHistory(h => [...h, next]);
    const img = new Image();
    img.onload = () => {
      const ctx = canvasRef.current.getContext('2d');
      ctx.clearRect(0, 0, canvasSize.w, canvasSize.h);
      ctx.drawImage(img, 0, 0, canvasSize.w, canvasSize.h);
    };
    img.src = next;
  };

  const clearCanvas = () => {
    const ctx = canvasRef.current.getContext('2d');
    ctx.fillStyle = '#080810';
    ctx.fillRect(0, 0, canvasSize.w, canvasSize.h);
    saveHistory();
  };

  const saveImage = () => {
    const canvas = canvasRef.current;
    const link = document.createElement('a');
    link.download = 'lithe-sketch.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const addSticker = (sticker) => {
    const ctx = canvasRef.current.getContext('2d');
    ctx.font = `${size * 6}px serif`;
    ctx.fillText(sticker, canvasSize.w/2, canvasSize.h/2);
    saveHistory();
    setShowStickers(false);
  };

  const addText = () => {
    const text = prompt('Enter text:');
    if (!text) return;
    const ctx = canvasRef.current.getContext('2d');
    ctx.font = `${size * 4}px "IBM Plex Mono"`;
    ctx.fillStyle = color;
    ctx.globalAlpha = opacity;
    ctx.fillText(text, canvasSize.w/2 - ctx.measureText(text).width/2, canvasSize.h/2);
    ctx.globalAlpha = 1;
    saveHistory();
  };

  const filterStyle = {
    none: 'none',
    grayscale: 'grayscale(100%)',
    sepia: 'sepia(80%)',
    invert: 'invert(100%)',
    blur: 'blur(1px)',
    saturate: 'saturate(200%)',
  }[filter] || 'none';

  const S = {
    wrap: { fontFamily:"'IBM Plex Mono',monospace", color:'#b8a8d4', display:'flex', flexDirection:'column', height:'100%', minHeight:'100vh', background:'#080810' },
    toolbar: { background:'#0d0b16', borderBottom:'0.5px solid #2a1e42', padding:'0.5rem 0.75rem', display:'flex', gap:'0.35rem', flexWrap:'wrap', alignItems:'center' },
    btn: (active) => ({ background: active?'#1a1228':'transparent', border:`0.5px solid ${active?'#7b3fff':'#2a1e42'}`, color: active?'#d0b0ff':'#5a4a8a', fontFamily:'inherit', fontSize:'0.55rem', padding:'0.3rem 0.45rem', borderRadius:'4px', cursor:'pointer', display:'flex', flexDirection:'column', alignItems:'center', gap:'1px' }),
    iconBtn: (active) => ({ background: active?'#1a1228':'transparent', border:`0.5px solid ${active?'#7b3fff':'#2a1e42'}`, color: active?'#d0b0ff':'#5a4a8a', fontFamily:'inherit', fontSize:'0.55rem', padding:'0.28rem 0.4rem', borderRadius:'4px', cursor:'pointer' }),
    colorDot: (c, active) => ({ width:18, height:18, borderRadius:'50%', background:c, cursor:'pointer', flexShrink:0, border: active?'2px solid #fff':'2px solid transparent', transition:'border 0.1s' }),
    panel: { background:'#0d0b16', borderBottom:'0.5px solid #1e1530', padding:'0.4rem 0.75rem', display:'flex', gap:'0.5rem', alignItems:'center', flexWrap:'wrap' },
    canvasWrap: { flex:1, overflow:'auto', display:'flex', alignItems:'flex-start', justifyContent:'flex-start', background:'#04040a', padding:'0.5rem', position:'relative' },
    label: { fontSize:'0.48rem', color:'#3a2a5a', letterSpacing:'0.15em', textTransform:'uppercase', marginBottom:'2px' },
  };

  return (
    <div style={S.wrap}>
      {/* Brush toolbar */}
      <div style={S.toolbar}>
        {BRUSHES.map(b => (
          <button key={b.id} onClick={() => setBrush(b.id)} style={S.btn(brush===b.id)}>
            <i className={`ti ${b.icon}`} style={{fontSize:16}}/>
            <span style={{fontSize:'0.42rem'}}>{b.label}</span>
          </button>
        ))}
        <div style={{marginLeft:'auto', display:'flex', gap:'0.3rem'}}>
          <button onClick={addText} style={S.iconBtn(false)} title="Add text">
            <i className="ti ti-letter-t" style={{fontSize:15}}/>
          </button>
          <button onClick={() => setShowStickers(s=>!s)} style={S.iconBtn(showStickers)} title="Stickers">
            <i className="ti ti-mood-smile" style={{fontSize:15}}/>
          </button>
          <button onClick={() => setShowGrid(g=>!g)} style={S.iconBtn(showGrid)} title="Grid">
            <i className="ti ti-grid-dots" style={{fontSize:15}}/>
          </button>
          <button onClick={() => setSymmetry(s=>!s)} style={S.iconBtn(symmetry)} title="Symmetry">
            <i className="ti ti-arrows-left-right" style={{fontSize:15}}/>
          </button>
          <button onClick={() => setShowLayers(l=>!l)} style={S.iconBtn(showLayers)} title="Layers">
            <i className="ti ti-layers-subtract" style={{fontSize:15}}/>
          </button>
        </div>
      </div>

      {/* Color + size + opacity bar */}
      <div style={S.panel}>
        <div>
          <div style={S.label}>Colors</div>
          <div style={{display:'flex', gap:'0.25rem', flexWrap:'wrap', maxWidth:220}}>
            {COLORS.map(c => (
              <div key={c} onClick={() => setColor(c)} style={S.colorDot(c, color===c)}/>
            ))}
            <input type="color" value={customColor} onChange={e=>{setCustomColor(e.target.value);setColor(e.target.value);}}
              style={{width:18,height:18,borderRadius:'50%',border:'none',padding:0,cursor:'pointer',background:'transparent'}} title="Custom color"/>
          </div>
        </div>
        <div style={{marginLeft:'auto'}}>
          <div style={S.label}>Size</div>
          <div style={{display:'flex', gap:'0.25rem', alignItems:'center'}}>
            {SIZES.map(s => (
              <div key={s} onClick={() => setSize(s)} style={{
                width: s*1.5+8, height: s*1.5+8, borderRadius:'50%',
                background: size===s ? color : '#2a1e42',
                cursor:'pointer', border: size===s?`2px solid ${color}`:'2px solid transparent',
                transition:'all 0.15s', flexShrink:0,
              }}/>
            ))}
          </div>
        </div>
      </div>

      {/* Opacity + filter bar */}
      <div style={{...S.panel, gap:'0.75rem'}}>
        <div style={{display:'flex', alignItems:'center', gap:'0.5rem', flex:1}}>
          <span style={{fontSize:'0.5rem', color:'#3a2a5a', letterSpacing:'0.15em', textTransform:'uppercase', whiteSpace:'nowrap'}}>Opacity</span>
          <input type="range" min="0.05" max="1" step="0.05" value={opacity} onChange={e=>setOpacity(parseFloat(e.target.value))}
            style={{flex:1, accentColor:'#7b3fff'}}/>
          <span style={{fontSize:'0.58rem', color:'#7b3fff', minWidth:30}}>{Math.round(opacity*100)}%</span>
        </div>
        <div style={{display:'flex', gap:'0.25rem', flexWrap:'wrap'}}>
          {FILTERS.map(f => (
            <button key={f.id} onClick={() => setFilter(f.id)} style={{
              ...S.iconBtn(filter===f.id), fontSize:'0.5rem', padding:'0.22rem 0.4rem'
            }}>{f.label}</button>
          ))}
        </div>
      </div>

      {/* Actions */}
      <div style={{...S.panel, gap:'0.3rem'}}>
        <button onClick={undo} style={S.iconBtn(false)} disabled={history.length<2}>
          <i className="ti ti-arrow-back-up" style={{fontSize:14}}/></button>
        <button onClick={redo} style={S.iconBtn(false)} disabled={!redoStack.length}>
          <i className="ti ti-arrow-forward-up" style={{fontSize:14}}/></button>
        <div style={{width:'0.5px', background:'#2a1e42', height:20, margin:'0 0.2rem'}}/>
        <button onClick={clearCanvas} style={{...S.iconBtn(false), color:'#c07070', borderColor:'#5a2a2a'}}>
          <i className="ti ti-trash" style={{fontSize:14}}/></button>
        <button onClick={saveImage} style={{...S.iconBtn(false), color:'#7ecfc0', borderColor:'#2a5a4a', marginLeft:'auto', display:'flex', alignItems:'center', gap:4, padding:'0.28rem 0.65rem'}}>
          <i className="ti ti-download" style={{fontSize:14}}/> <span style={{fontSize:'0.55rem'}}>Save</span>
        </button>
        <div style={{display:'flex', alignItems:'center', gap:'0.3rem'}}>
          <span style={{fontSize:'0.5rem', color:'#3a2a5a'}}>Zoom</span>
          <button onClick={() => setZoom(z => Math.max(0.25, z-0.25))} style={{...S.iconBtn(false), padding:'0.22rem 0.35rem'}}>-</button>
          <span style={{fontSize:'0.55rem', color:'#7b3fff', minWidth:30, textAlign:'center'}}>{Math.round(zoom*100)}%</span>
          <button onClick={() => setZoom(z => Math.min(3, z+0.25))} style={{...S.iconBtn(false), padding:'0.22rem 0.35rem'}}>+</button>
        </div>
      </div>

      {/* Sticker picker */}
      {showStickers && (
        <div style={{background:'#0d0b16', border:'0.5px solid #3a2a5a', padding:'0.5rem', display:'flex', flexWrap:'wrap', gap:'0.35rem'}}>
          {STICKERS.map(s => (
            <button key={s} onClick={() => addSticker(s)} style={{
              background:'#0a0814', border:'0.5px solid #2a1e42', borderRadius:'4px',
              fontSize:'1.3rem', padding:'0.3rem 0.4rem', cursor:'pointer',
            }}>{s}</button>
          ))}
        </div>
      )}

      {/* Layers panel */}
      {showLayers && (
        <div style={{background:'#0d0b16', border:'0.5px solid #3a2a5a', padding:'0.6rem 0.75rem'}}>
          <div style={{fontSize:'0.52rem', color:'#4a3a6a', letterSpacing:'0.2em', textTransform:'uppercase', marginBottom:'0.5rem'}}>Layers</div>
          {layers.map((l, i) => (
            <div key={l.id} onClick={() => setLayer(i)} style={{
              display:'flex', alignItems:'center', gap:'0.5rem', padding:'0.35rem 0.5rem',
              background: layer===i ? '#1a1228' : 'transparent',
              border: `0.5px solid ${layer===i ? '#7b3fff' : '#2a1e42'}`,
              borderRadius:'4px', marginBottom:'0.3rem', cursor:'pointer',
            }}>
              <i className="ti ti-square" style={{fontSize:12, color: layer===i?'#d0b0ff':'#4a3a6a'}}/>
              <span style={{fontSize:'0.62rem', flex:1, color: layer===i?'#d0b0ff':'#7a5a9a'}}>{l.name}</span>
              <button onClick={e=>{e.stopPropagation();setLayers(ls=>ls.map((ll,li)=>li===i?{...ll,visible:!ll.visible}:ll));}} style={{background:'transparent',border:'none',color:'#4a3a6a',cursor:'pointer',padding:0}}>
                <i className={`ti ${l.visible?'ti-eye':'ti-eye-off'}`} style={{fontSize:12}}/>
              </button>
            </div>
          ))}
          <button onClick={() => {
            const newLayer = {id:Date.now(), name:`Layer ${layers.length+1}`, visible:true, opacity:1};
            setLayers(ls=>[...ls, newLayer]);
            setLayer(layers.length);
          }} style={{...S.iconBtn(false), width:'100%', justifyContent:'center', marginTop:'0.3rem', fontSize:'0.55rem', display:'flex', alignItems:'center', gap:4}}>
            <i className="ti ti-plus" style={{fontSize:12}}/> Add layer
          </button>
        </div>
      )}

      {/* Canvas */}
      <div style={S.canvasWrap}>
        <div style={{position:'relative', transform:`scale(${zoom})`, transformOrigin:'top left'}}>
          <canvas ref={canvasRef} style={{display:'block', filter:filterStyle, cursor: brush==='eraser'?'cell':brush==='fill'?'crosshair':'default'}}
            onMouseDown={startDraw} onMouseMove={continueDraw} onMouseUp={endDraw} onMouseLeave={endDraw}
            onTouchStart={startDraw} onTouchMove={continueDraw} onTouchEnd={endDraw}/>
          <canvas ref={overlayRef} width={canvasSize.w} height={canvasSize.h}
            style={{position:'absolute',top:0,left:0,pointerEvents:'none',width:canvasSize.w,height:canvasSize.h}}/>
          {showGrid && (
            <div style={{position:'absolute',top:0,left:0,width:canvasSize.w,height:canvasSize.h,pointerEvents:'none',
              backgroundImage:'linear-gradient(#2a1e4222 1px,transparent 1px),linear-gradient(90deg,#2a1e4222 1px,transparent 1px)',
              backgroundSize:'40px 40px'}}/>
          )}
          {symmetry && (
            <div style={{position:'absolute',top:0,left:'50%',width:'0.5px',height:'100%',background:'#7b3fff44',pointerEvents:'none'}}/>
          )}
        </div>
      </div>

      {/* Status bar */}
      <div style={{background:'#0a0814', borderTop:'0.5px solid #1e1530', padding:'0.25rem 0.75rem', display:'flex', gap:'0.75rem', alignItems:'center'}}>
        <div style={{display:'flex', alignItems:'center', gap:5}}>
          <div style={{width:10, height:10, borderRadius:'50%', background:color, border:'1px solid #4a3a6a'}}/>
          <span style={{fontSize:'0.5rem', color:'#3a2a5a'}}>{color}</span>
        </div>
        <span style={{fontSize:'0.5rem', color:'#3a2a5a'}}>
          {brush} · size {size} · {Math.round(opacity*100)}% opacity
        </span>
        {symmetry && <span style={{fontSize:'0.5rem', color:'#7b3fff'}}>symmetry on</span>}
        {showGrid && <span style={{fontSize:'0.5rem', color:'#5a4a8a'}}>grid on</span>}
        <span style={{fontSize:'0.5rem', color:'#2a1e42', marginLeft:'auto'}}>{canvasSize.w}×{canvasSize.h}</span>
      </div>
    </div>
  );
}
