const CAPTURE_TIPS = [
  "Always check: what is the opponent's most dangerous threat before you capture?",
  "Free pieces should almost always be captured — unless there's a tactical trick.",
  "A good trade gives up equal or lesser value for something more valuable.",
  "Capturing toward the center is usually better than capturing away from it.",
];
const CHECK_TIPS = [
  "When in check, you must deal with it immediately — move the king, block, or capture the attacker.",
  "Not all checks are good. Only check if it creates a real threat or gains material.",
  "Perpetual check (checking endlessly) forces a draw — useful when you're losing.",
];

const AI_MOVE_EXPLAIN = {
  P: (sq) => `The computer advanced a pawn to ${sq}. Pawns control space and can promote — never ignore them.`,
  N: (sq) => `Knight to ${sq}. The computer is developing toward the center — a key opening principle.`,
  B: (sq) => `Bishop to ${sq}. Watch the diagonal this bishop now controls — it may be targeting your pieces.`,
  R: (sq) => `Rook to ${sq}. The computer is claiming an open file — rooks belong on open lines.`,
  Q: (sq) => `Queen to ${sq}. A powerful move — scan all the squares this queen now threatens.`,
  K: (sq) => `King moved to ${sq}. Either castling for safety or activating in the endgame.`,
};

export function getTutorComment({ move, prevFen, fen, isAI, quality, moveNumber, isCheck, isCheckmate, isCoachMode }) {
  const chess = new Chess(fen);
  const sq = move.to;
  const piece = move.piece?.toUpperCase() || 'P';
  const captured = move.captured;
  const isOpening = moveNumber <= 10;
  const isEndgame = chess.board().flat().filter(Boolean).length <= 12;

  // Checkmate
  if (isCheckmate) {
    if (isAI) return {
      tone: 'blunder',
      label: 'Checkmate — computer wins',
      text: `The computer delivered checkmate. Your king had no safe squares left. Study the final position — where did the attack start?`,
      tip: 'Next game: castle early and keep pawns in front of your king. Don\'t let open files point at your king.',
      emoji: '💀',
    };
    return {
      tone: 'brilliant',
      label: 'Checkmate — you won!',
      text: `You checkmated the computer! The king had nowhere to go. That\'s the goal of every game of chess.`,
      tip: 'Well played. Notice how your pieces coordinated to cut off all escape squares.',
      emoji: '🏆',
    };
  }

  // Check
  if (isCheck && !isAI) {
    return {
      tone: 'good',
      label: 'Check!',
      text: `You put the computer in check! Its king must move, block, or capture the attacker right now.`,
      tip: rand(CHECK_TIPS),
      emoji: '⚡',
    };
  }

  if (isCheck && isAI) {
    return {
      tone: 'warn',
      label: 'You\'re in check!',
      text: `The computer put your king in check. You must respond immediately — move the king to safety, block with another piece, or capture the attacker.`,
      tip: rand(CHECK_TIPS),
      emoji: '⚠️',
    };
  }

  // AI move explanation
  if (isAI) {
    const explain = AI_MOVE_EXPLAIN[piece]?.(sq) || `The computer moved its ${pn(move.piece)} to ${sq}.`;
    const capMsg = captured ? ` It captured your ${pn(captured)} — material is now unequal.` : '';
    const tipMap = { P: PAWN_TIPS, N: KNIGHT_TIPS, B: BISHOP_TIPS, R: ROOK_TIPS, Q: QUEEN_TIPS, K: KING_TIPS };
    return {
      tone: 'ai',
      label: 'Computer played',
      text: explain + capMsg + ' Now — what is the computer\'s biggest threat? Think before you move.',
      tip: rand(captured ? CAPTURE_TIPS : (tipMap[piece] || PAWN_TIPS)),
      emoji: '🤖',
    };
  }

  // Player move — quality based
  const qualityEmojis = { brilliant: '✨', best: '⭐', excellent: '✅', good: '👍', interesting: '🤔', inaccuracy: '⚠️', mistake: '❌', blunder: '💥' };
  const qualityColors = { brilliant: 'brilliant', best: 'best', excellent: 'excellent', good: 'good', interesting: 'interesting', inaccuracy: 'inaccuracy', mistake: 'mistake', blunder: 'blunder' };

  let text = '';
  let tip = '';

  if (quality === 'blunder') {
    const blunderReasons = {
      Q: `You moved your queen to ${sq} but it can now be attacked, or it left another piece undefended. Losing your queen is almost always game-over.`,
      N: `Your knight moved to ${sq} but it left a piece undefended behind it — check if you left something hanging.`,
      P: `That pawn push to ${sq} may have opened a line to your king, or left a piece without protection.`,
    };
    text = blunderReasons[piece] || `That move to ${sq} was a blunder — it either lost material, opened your king, or created a serious weakness. Take a breath and look at what the computer can do now.`;
    tip = 'Before every move, ask: "After I move, what can my opponent do?" This one question prevents most blunders.';
  } else if (quality === 'mistake') {
    text = `${pn(move.piece).charAt(0).toUpperCase() + pn(move.piece).slice(1)} to ${sq} gave the computer an advantage. You had a better option available.`;
    tip = 'When you see a good move, look for a better one before playing it.';
  } else if (quality === 'inaccuracy') {
    text = `${pn(move.piece).charAt(0).toUpperCase() + pn(move.piece).slice(1)} to ${sq} — not wrong, but there was a slightly stronger option. Still playable.`;
    tip = isOpening ? rand(OPENING_TIPS) : 'Small inaccuracies add up over time. Try to find the most active square for each piece.';
  } else if (quality === 'good' || quality === 'interesting') {
    const goodMsgs = {
      P: captured
        ? `You captured on ${sq} with your pawn — great. Pawns capturing toward the center is usually best.`
        : isOpening
          ? `Pawn to ${sq}. ${['e4','d4','e5','d5'].includes(sq) ? 'Excellent center control — this is textbook.' : 'Solid pawn move. Keep developing your pieces now.'}`
          : `Pawn to ${sq}. Every pawn push changes the structure permanently — think about the long-term implications.`,
      N: `Knight to ${sq}. ${isOpening ? 'Good development — knights belong in the center.' : 'Active knight placement. Check the squares it now controls.'}`,
      B: `Bishop to ${sq}. ${isOpening ? 'Good development.' : 'That diagonal is now active.'} Look at what your bishop controls from here.`,
      R: `Rook to ${sq}. ${isOpening ? 'Rooks are usually activated after castling.' : 'Good rook placement — is that file open?'}`,
      Q: `Queen to ${sq}. Active queen move. Make sure she can\'t be chased away by cheap pieces.`,
      K: isEndgame ? `King to ${sq}. Good — in the endgame, an active king is a winning king.` : `King to ${sq}. Make sure this is safe.`,
    };
    text = goodMsgs[piece] || `${pn(move.piece)} to ${sq} — solid move.`;
    const tipMap = { P: PAWN_TIPS, N: KNIGHT_TIPS, B: BISHOP_TIPS, R: ROOK_TIPS, Q: QUEEN_TIPS, K: isEndgame ? KING_TIPS : OPENING_TIPS };
    tip = rand(isOpening ? OPENING_TIPS : (tipMap[piece] || PAWN_TIPS));
  } else if (quality === 'excellent' || quality === 'best' || quality === 'brilliant') {
    text = quality === 'brilliant'
      ? `Brilliant move! ${pn(move.piece)} to ${sq}${captured ? `, capturing the ${pn(captured)}` : ''} — that\'s a strong, unexpected idea that creates real problems for the computer.`
      : quality === 'best'
        ? `Best move! ${pn(move.piece)} to ${sq} — this is exactly what a strong player would play here.`
        : `Excellent! ${pn(move.piece)} to ${sq}${captured ? `, taking the ${pn(captured)}` : ''} — strong decision.`;
    const tipMap = { P: PAWN_TIPS, N: KNIGHT_TIPS, B: BISHOP_TIPS, R: ROOK_TIPS, Q: QUEEN_TIPS, K: KING_TIPS };
    tip = rand(tipMap[piece] || PAWN_TIPS);
  }

  // Coach mode — ask questions instead of telling
  if (isCoachMode && (quality === 'blunder' || quality === 'mistake')) {
    return {
      tone: qualityColors[quality],
      label: quality.charAt(0).toUpperCase() + quality.slice(1),
      text: `That move had a problem. Before I explain — can you see it? Look at the board: which of your pieces is now undefended or in danger?`,
      tip: 'In coach mode, try to find the mistake yourself first. This trains your pattern recognition.',
      emoji: qualityEmojis[quality],
      isQuestion: true,
    };
  }

  return {
    tone: qualityColors[quality] || 'info',
    label: quality?.charAt(0).toUpperCase() + quality?.slice(1) || 'Move made',
    text,
    tip,
    emoji: qualityEmojis[quality] || '♟',
  };
}

export function getHint(fen, level = 1) {
  const chess = new Chess(fen);
  if (level === 1) {
    // Vague strategic hint
    const hints = [
      'Think about king safety — is your king well protected?',
      'Look for undefended pieces on both sides of the board.',
      'Consider developing a piece that hasn\'t moved yet.',
      'Is there a way to control more of the center?',
      'Check if any of your pieces are being attacked right now.',
    ];
    return { level: 1, text: rand(hints) };
  }
  if (level === 2) {
    // Piece-level hint
    const moves = chess.moves({ verbose: true });
    const captures = moves.filter(m => m.captured);
    if (captures.length) {
      const cap = captures[0];
      return { level: 2, text: `There's a capture available — consider moving your ${pn(cap.piece)} on ${cap.from}.` };
    }
    const checks = moves.filter(m => m.san.includes('+'));
    if (checks.length) {
      return { level: 2, text: `You have a check available. Look for a move that puts the enemy king in check.` };
    }
    return { level: 2, text: `Consider moving your ${pn(moves[0]?.piece || 'p')} — it may create useful threats.` };
  }
  // Level 3 — exact move
  const { getTopMoves } = require('./chessAI');
  const top = getTopMoves(fen, 1);
  if (top[0]) {
    return { level: 3, text: `The best move here is ${top[0].san} — ${pn(top[0].piece)} from ${top[0].from} to ${top[0].to}.` };
  }
  return { level: 3, text: 'Play the move that develops your least-active piece toward the center.' };
}
