import { Chess } from 'chess.js';

const PIECE_VALUES = { p: 100, n: 320, b: 330, r: 500, q: 900, k: 20000 };

const PAWN_TABLE = [
  0,  0,  0,  0,  0,  0,  0,  0,
  50, 50, 50, 50, 50, 50, 50, 50,
  10, 10, 20, 30, 30, 20, 10, 10,
   5,  5, 10, 25, 25, 10,  5,  5,
   0,  0,  0, 20, 20,  0,  0,  0,
   5, -5,-10,  0,  0,-10, -5,  5,
   5, 10, 10,-20,-20, 10, 10,  5,
   0,  0,  0,  0,  0,  0,  0,  0
];
const KNIGHT_TABLE = [
  -50,-40,-30,-30,-30,-30,-40,-50,
  -40,-20,  0,  0,  0,  0,-20,-40,
  -30,  0, 10, 15, 15, 10,  0,-30,
  -30,  5, 15, 20, 20, 15,  5,-30,
  -30,  0, 15, 20, 20, 15,  0,-30,
  -30,  5, 10, 15, 15, 10,  5,-30,
  -40,-20,  0,  5,  5,  0,-20,-40,
  -50,-40,-30,-30,-30,-30,-40,-50
];
const BISHOP_TABLE = [
  -20,-10,-10,-10,-10,-10,-10,-20,
  -10,  0,  0,  0,  0,  0,  0,-10,
  -10,  0,  5, 10, 10,  5,  0,-10,
  -10,  5,  5, 10, 10,  5,  5,-10,
  -10,  0, 10, 10, 10, 10,  0,-10,
  -10, 10, 10, 10, 10, 10, 10,-10,
  -10,  5,  0,  0,  0,  0,  5,-10,
  -20,-10,-10,-10,-10,-10,-10,-20
];
const ROOK_TABLE = [
   0,  0,  0,  0,  0,  0,  0,  0,
   5, 10, 10, 10, 10, 10, 10,  5,
  -5,  0,  0,  0,  0,  0,  0, -5,
  -5,  0,  0,  0,  0,  0,  0, -5,
  -5,  0,  0,  0,  0,  0,  0, -5,
  -5,  0,  0,  0,  0,  0,  0, -5,
  -5,  0,  0,  0,  0,  0,  0, -5,
   0,  0,  0,  5,  5,  0,  0,  0
];
const QUEEN_TABLE = [
  -20,-10,-10, -5, -5,-10,-10,-20,
  -10,  0,  0,  0,  0,  0,  0,-10,
  -10,  0,  5,  5,  5,  5,  0,-10,
   -5,  0,  5,  5,  5,  5,  0, -5,
    0,  0,  5,  5,  5,  5,  0, -5,
  -10,  5,  5,  5,  5,  5,  0,-10,
  -10,  0,  5,  0,  0,  0,  0,-10,
  -20,-10,-10, -5, -5,-10,-10,-20
];
const KING_MID_TABLE = [
  -30,-40,-40,-50,-50,-40,-40,-30,
  -30,-40,-40,-50,-50,-40,-40,-30,
  -30,-40,-40,-50,-50,-40,-40,-30,
  -30,-40,-40,-50,-50,-40,-40,-30,
  -20,-30,-30,-40,-40,-30,-30,-20,
  -10,-20,-20,-20,-20,-20,-20,-10,
   20, 20,  0,  0,  0,  0, 20, 20,
   20, 30, 10,  0,  0, 10, 30, 20
];

const TABLES = { p: PAWN_TABLE, n: KNIGHT_TABLE, b: BISHOP_TABLE, r: ROOK_TABLE, q: QUEEN_TABLE, k: KING_MID_TABLE };

function squareIndex(square, color) {
  const file = square.charCodeAt(0) - 97;
  const rank = 8 - parseInt(square[1]);
  const idx = rank * 8 + file;
  return color === 'w' ? (56 - rank * 8) + file : idx;
}

function evalBoard(chess) {
  let score = 0;
  const board = chess.board();
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      const piece = board[r][c];
      if (!piece) continue;
      const val = PIECE_VALUES[piece.type] || 0;
      const sq = String.fromCharCode(97 + c) + (8 - r);
      const tableIdx = squareIndex(sq, piece.color);
      const bonus = TABLES[piece.type] ? (TABLES[piece.type][tableIdx] || 0) : 0;
      score += piece.color === 'w' ? (val + bonus) : -(val + bonus);
    }
  }
  return score;
}

// Level-based error injection
function shouldBlunder(level) {
  const blunderRates = [0.9, 0.7, 0.5, 0.35, 0.2, 0.12, 0.07, 0.04, 0.02, 0.01, 0, 0, 0, 0, 0];
  return Math.random() < (blunderRates[level] || 0);
}

function getDepth(level) {
  if (level <= 1) return 1;
  if (level <= 3) return 1;
  if (level <= 5) return 2;
  if (level <= 8) return 2;
  if (level <= 11) return 3;
  return 4;
}

function minimax(chess, depth, alpha, beta, maximizing) {
  if (depth === 0 || chess.isGameOver()) {
    if (chess.isCheckmate()) return maximizing ? -99999 : 99999;
    if (chess.isDraw()) return 0;
    return evalBoard(chess);
  }
  const moves = chess.moves({ verbose: true });
  moves.sort(() => Math.random() - 0.5);

  if (maximizing) {
    let best = -Infinity;
    for (const move of moves) {
      chess.move(move);
      best = Math.max(best, minimax(chess, depth - 1, alpha, beta, false));
      chess.undo();
      alpha = Math.max(alpha, best);
      if (beta <= alpha) break;
    }
    return best;
  } else {
    let best = Infinity;
    for (const move of moves) {
      chess.move(move);
      best = Math.min(best, minimax(chess, depth - 1, alpha, beta, true));
      chess.undo();
      beta = Math.min(beta, best);
      if (beta <= alpha) break;
    }
    return best;
  }
}

export function getBestMove(fen, level = 5) {
  const chess = new Chess(fen);
  const moves = chess.moves({ verbose: true });
  if (!moves.length) return null;

  // Blunder / random play for low levels
  if (shouldBlunder(level)) {
    return moves[Math.floor(Math.random() * moves.length)];
  }

  const depth = getDepth(level);
  let bestMove = null;
  let bestScore = Infinity;

  for (const move of moves) {
    chess.move(move);
    const score = minimax(chess, depth - 1, -Infinity, Infinity, true);
    chess.undo();
    if (score < bestScore) {
      bestScore = score;
      bestMove = move;
    }
  }
  return bestMove;
}

export function getTopMoves(fen, count = 3) {
  const chess = new Chess(fen);
  const moves = chess.moves({ verbose: true });
  const scored = [];
  for (const move of moves) {
    chess.move(move);
    const score = -evalBoard(chess);
    chess.undo();
    scored.push({ move, score });
  }
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, count).map(s => s.move);
}

export function evaluateMove(prevFen, move, fen) {
  const prev = new Chess(prevFen);
  const after = new Chess(fen);
  const bestMoves = getTopMoves(prevFen, 3);
  const isBest = bestMoves.some(m => m.from === move.from && m.to === move.to);

  const prevScore = evalBoard(prev);
  const afterScore = evalBoard(after);
  const delta = afterScore - prevScore;

  let quality, label;
  if (after.isCheckmate()) { quality = 'brilliant'; label = 'Checkmate!'; }
  else if (isBest && delta >= 0) { quality = 'best'; label = 'Best move'; }
  else if (delta >= 50) { quality = 'excellent'; label = 'Excellent'; }
  else if (delta >= 10) { quality = 'good'; label = 'Good'; }
  else if (delta >= -10) { quality = 'interesting'; label = 'Interesting'; }
  else if (delta >= -50) { quality = 'inaccuracy'; label = 'Inaccuracy'; }
  else if (delta >= -150) { quality = 'mistake'; label = 'Mistake'; }
  else { quality = 'blunder'; label = 'Blunder'; }

  return { quality, label, delta, isBest };
}
