import React, { useState, useEffect, useRef } from 'react';
import ChessGame from './components/ChessGame';
import PieceGuide from './components/PieceGuide';
import SketchPad from './components/SketchPad';
import './App.css';

const QUOTES = [
  { q: "The world is not beautiful. Therefore it is.", src: "Kino's Journey" },
  { q: "If you don't take risks, you can't create a future.", src: "One Piece" },
  { q: "Whatever you lose, you'll find it again. But what you throw away you'll never get back.", src: "Fullmetal Alchemist" },
  { q: "Even if I can't see you, I'll keep moving forward.", src: "Violet Evergarden" },
  { q: "A person grows when she surpasses what she once thought was her limit.", src: "Bleach" },
  { q: "No matter how deep the night, it always turns to day.", src: "One Piece" },
  { q: "The only home you have is the one you build yourself.", src: "Made in Abyss" },
];

const FACTS = [
  "Neutron stars are so dense that a teaspoon would weigh a billion tons on Earth.",
  "There are more possible chess games than atoms in the observable universe.",
  "GPS satellites must correct for time dilation — time moves faster in orbit.",
  "Voyager 1 is 24 billion km away, still transmitting on 1970s hardware.",
  "If you removed all empty space from every human atom, all of humanity would fit in a sugar cube.",
  "A day on Venus is longer than its year — it rotates slower than it orbits the sun.",
  "Sunlight reaching your eyes left the sun 8 minutes ago.",
];

const QUIZ = [
  { q: "She has zero cursed energy but became one of the strongest through pure physical training.", opts: ["Nobara Kugisaki","Maki Zenin","Rukia Kuchiki","Erza Scarlet"], ans: 1 },
  { q: "A cyborg who questions whether identity and consciousness can survive in a manufactured body.", opts: ["Android 18","Rei Ayanami","Major Motoko Kusanagi","Alita"], ans: 2 },
  { q: "She uses a hammer and nails as weapons and has zero apologies for who she is.", opts: ["Erza Scarlet","Maki Zenin","Nobara Kugisaki","Revy"], ans: 2 },
  { q: "Commands a demon-hunting organization. Never raises her voice. Never has to.", opts: ["Mirko","Cornelia li Britannia","Lady Dimitrescu","Integra Hellsing"], ans: 3 },
  { q: "Her story is about rebuilding yourself after being stripped of everything — autonomy, memory, even the ability to feel.", opts: ["Nana","Violet Evergarden","Tohru Honda","Shouko"], ans: 1 },
  { q: "She plays basketball, draws, loves anime, studies land economy, and moves through every room like she already knows how it ends.", opts: ["A fictional character","Someone from an anime","Just a guess","Aba Kwansma — Lithe"], ans: 3 },
];

export default function App() {
  const [tab, setTab] = useState('daily');
  const [qi, setQi] = useState(0);
  const [qs, setQs] = useState(0);
  const [qdone, setQdone] = useState(false);
  const [answered, setAnswered] = useState(null);
  const [world, setWorld] = useState(() => { try { return JSON.parse(localStorage.getItem('lithe_world')) || {shows:[],quotes:[],chars:[]}; } catch { return {shows:[],quotes:[],chars:[]}; }});
  const [wtab, setWtab] = useState('shows');
  const [winput, setWinput] = useState({shows:'',quotes:'',chars:''});
  const [dcolor, setDcolor] = useState('#d0b0ff');
  const canvasRef = useRef(null);
  const drawRef = useRef({drawing:false,lx:0,ly:0});
  const now = new Date();
  const q = QUOTES[now.getDate() % QUOTES.length];
  const f = FACTS[now.getDate() % FACTS.length];

  useEffect(() => { try { localStorage.setItem('lithe_world', JSON.stringify(world)); } catch {} }, [world]);

  useEffect(() => {
    if (tab !== 'daily') return;
    setTimeout(() => {
      const c = canvasRef.current; if (!c) return;
      const dpr = window.devicePixelRatio || 1;
      c.width = c.offsetWidth * dpr; c.height = 130 * dpr;
      c.getContext('2d').scale(dpr, dpr);
    }, 100);
  }, [tab]);

  function getPos(e, c) {
    const r = c.getBoundingClientRect();
    const s = e.touches ? e.touches[0] : e;
    return [s.clientX - r.left, s.clientY - r.top];
  }
  function sd(e) {
    const c = canvasRef.current; if (!c) return;
    const [x,y] = getPos(e,c); drawRef.current = {drawing:true,lx:x,ly:y};
    if (e.touches) e.preventDefault();
  }
  function dr(e) {
    const c = canvasRef.current; const d = drawRef.current;
    if (!c || !d.drawing) return;
    const ctx = c.getContext('2d');
    const [x,y] = getPos(e,c);
    ctx.beginPath(); ctx.moveTo(d.lx,d.ly); ctx.lineTo(x,y);
    ctx.strokeStyle=dcolor; ctx.lineWidth=2; ctx.lineCap='round'; ctx.stroke();
    drawRef.current = {...d,lx:x,ly:y};
    if (e.touches) e.preventDefault();
  }
  function ed() { drawRef.current.drawing = false; }
  function clr() { const c=canvasRef.current; if(c) c.getContext('2d').clearRect(0,0,c.width,c.height); }

  function ansQ(i) {
    if (answered !== null) return;
    setAnswered(i);
    if (i === QUIZ[qi].ans) setQs(s => s+1);
  }
  function nextQ() {
    if (qi+1 >= QUIZ.length) { setQdone(true); return; }
    setQi(i=>i+1); setAnswered(null);
  }
  function addW() {
    const v = winput[wtab].trim(); if (!v) return;
    setWorld(w => ({...w,[wtab]:[...w[wtab],v]}));
    setWinput(inp => ({...inp,[wtab]:''}));
  }
  function delW(t,i) { setWorld(w => ({...w,[t]:w[t].filter((_,idx)=>idx!==i)})); }

  const TABS = [
    {id:'daily',icon:'ti-sun',label:'Daily'},
    {id:'chess',icon:'ti-chess',label:'Chess'},
    {id:'draw',icon:'ti-brush',label:'Draw'},
    {id:'guide',icon:'ti-book',label:'Guide'},
    {id:'quiz',icon:'ti-help',label:'Quiz'},
    {id:'world',icon:'ti-planet',label:'World'},
  ];

  return (
    <div className="app">
      <div className="topbar">
        <div>
          <div className="logo-name">LITHE</div>
          <div className="logo-sub">Aba Kwansma</div>
        </div>
        <div style={{fontSize:'0.6rem',color:'#4a3a6a'}}>
          <span style={{display:'inline-block',width:6,height:6,background:'#7b3fff',borderRadius:'50%',marginRight:5,animation:'pulse 2.4s infinite',verticalAlign:'middle'}}/>
          {now.toLocaleDateString('en-GB',{day:'numeric',month:'short'})}
        </div>
      </div>

      <div className="content">
        {tab==='daily'&&(
          <div className="panel">
            <div className="sec-label"><span className="pulse"/>Today's transmission</div>
            <div className="quote-block">
              <div className="qt">"{q.q}"</div>
              <div className="qa">— {q.src}</div>
            </div>
            <div className="sec-label">Sci-fi fact</div>
            <div className="fact-box"><p className="fact-text">{f}</p></div>
            <div className="sec-label">Identity</div>
            <div className="tags">
              {['Feminist','Anime soul','Sci-fi','Artist','Land economy','Baller'].map(t=>(
                <div key={t} className="tag">{t}</div>
              ))}
            </div>
            <div className="sec-label">Sketch pad</div>
            <canvas ref={canvasRef} height={130} style={{background:'#0a0814',border:'0.5px solid #2a1e42',borderRadius:'4px',display:'block',width:'100%',touchAction:'none',cursor:'crosshair'}}
              onMouseDown={sd} onMouseMove={dr} onMouseUp={ed} onMouseLeave={ed}
              onTouchStart={sd} onTouchMove={dr} onTouchEnd={ed}/>
            <div style={{display:'flex',alignItems:'center',gap:'0.4rem',marginTop:'0.4rem'}}>
              {['#d0b0ff','#f9a8c9','#7ecfc0','#f0c060','#e0e0e0'].map(c=>(
                <div key={c} onClick={()=>setDcolor(c)} style={{width:16,height:16,borderRadius:'50%',background:c,cursor:'pointer',border:dcolor===c?'1.5px solid #fff':'1.5px solid transparent'}}/>
              ))}
              <button onClick={clr} style={{marginLeft:'auto',background:'transparent',border:'0.5px solid #2a1e42',color:'#4a3a6a',fontFamily:'inherit',fontSize:'0.55rem',padding:'0.22rem 0.5rem',borderRadius:'3px',cursor:'pointer'}}>clear</button>
            </div>
          </div>
        )}

        {tab==='chess'&&<ChessGame/>}
        {tab==='draw'&&<SketchPad/>}
        {tab==='guide'&&<PieceGuide/>}

        {tab==='quiz'&&(
          <div className="panel">
            <div className="sec-label">Anime character quiz</div>
            {!qdone?(
              <>
                <div style={{fontSize:'0.6rem',color:'#4a3a6a',marginBottom:'0.4rem'}}>Question {qi+1} of {QUIZ.length} — Score: {qs}</div>
                <div style={{height:'2px',background:'#1e1530',borderRadius:'1px',marginBottom:'1rem'}}>
                  <div style={{height:'2px',background:'#7b3fff',borderRadius:'1px',width:`${Math.round((qi/QUIZ.length)*100)}%`,transition:'width 0.4s'}}/>
                </div>
                <p style={{fontSize:'0.78rem',color:'#c0a8e8',lineHeight:1.8,marginBottom:'0.85rem',fontStyle:'italic'}}>{QUIZ[qi].q}</p>
                <div style={{display:'flex',flexDirection:'column',gap:'0.4rem',marginBottom:'0.75rem'}}>
                  {QUIZ[qi].opts.map((o,i)=>{
                    let bg='#0e0c18',border='#2a1e42',color='#b8a8d4';
                    if(answered!==null){
                      if(i===QUIZ[qi].ans){bg='#0a1a12';border='#2a6a3a';color='#7ecfc0';}
                      else if(i===answered){bg='#1a0a0a';border='#6a2a2a';color='#c07070';}
                    }
                    return(<button key={i} onClick={()=>ansQ(i)} style={{background:bg,border:`0.5px solid ${border}`,borderRadius:'4px',padding:'0.6rem 0.8rem',fontSize:'0.68rem',color,cursor:'pointer',textAlign:'left',fontFamily:'inherit',width:'100%'}}>{o}</button>);
                  })}
                </div>
                {answered!==null&&<button onClick={nextQ} style={{background:'#2a1a48',border:'0.5px solid #7b3fff',color:'#d0b0ff',fontFamily:'inherit',fontSize:'0.6rem',padding:'0.4rem 0.85rem',borderRadius:'4px',cursor:'pointer'}}>Next</button>}
              </>
            ):(
              <div>
                <div style={{textAlign:'center',marginBottom:'1rem'}}>
                  <i className="ti ti-lock-open" style={{fontSize:'2rem',color:'#7b3fff',display:'block',marginBottom:'0.5rem'}}/>
                  <div style={{fontSize:'0.7rem',color:'#b8a8d4'}}>Score: {qs} / {QUIZ.length} — Message unlocked.</div>
                </div>
                <div style={{background:'#0e0c18',border:'0.5px solid #5a2fa0',borderRadius:'6px',padding:'1.25rem',textAlign:'center'}}>
                  <p style={{fontSize:'0.78rem',fontStyle:'italic',color:'#c0a8e8',lineHeight:1.9}}>"You move through rooms like you already know how they end — quietly, with intention. That's rare. This was built for you because you deserved something that felt like it."</p>
                  <div style={{fontSize:'0.58rem',color:'#5a3a8a',marginTop:'0.75rem',letterSpacing:'0.15em'}}>— from Phil</div>
                </div>
                <button onClick={()=>{setQi(0);setQs(0);setQdone(false);setAnswered(null);}} style={{marginTop:'0.75rem',background:'#1a1228',border:'0.5px solid #3a2a5a',color:'#b8a8d4',fontFamily:'inherit',fontSize:'0.6rem',padding:'0.4rem 0.75rem',borderRadius:'4px',cursor:'pointer'}}>Play again</button>
              </div>
            )}
          </div>
        )}

        {tab==='world'&&(
          <div className="panel">
            <div className="sec-label">Her world</div>
            <div style={{display:'flex',gap:'0.35rem',marginBottom:'1rem'}}>
              {['shows','quotes','chars'].map(t=>(
                <button key={t} onClick={()=>setWtab(t)} style={{background:wtab===t?'#1a1228':'transparent',border:`0.5px solid ${wtab===t?'#5a2fa0':'#2a1e42'}`,color:wtab===t?'#d0b0ff':'#4a3a6a',fontFamily:'inherit',fontSize:'0.52rem',letterSpacing:'0.1em',padding:'0.28rem 0.55rem',borderRadius:'3px',cursor:'pointer',textTransform:'uppercase'}}>{t==='chars'?'Characters':t.charAt(0).toUpperCase()+t.slice(1)}</button>
              ))}
            </div>
            <div style={{display:'flex',gap:'0.4rem',marginBottom:'0.5rem'}}>
              <input value={winput[wtab]} onChange={e=>setWinput(inp=>({...inp,[wtab]:e.target.value}))} onKeyDown={e=>e.key==='Enter'&&addW()} placeholder={`Add a ${wtab==='chars'?'character':wtab.slice(0,-1)}...`} style={{flex:1,background:'#0e0c18',border:'0.5px solid #2a1e42',borderRadius:'4px',padding:'0.42rem 0.65rem',fontSize:'0.68rem',fontFamily:'inherit',color:'#b8a8d4',outline:'none'}}/>
              <button onClick={addW} style={{background:'#1a1228',border:'0.5px solid #3a2a5a',color:'#b8a8d4',fontFamily:'inherit',fontSize:'0.6rem',padding:'0.42rem 0.7rem',borderRadius:'4px',cursor:'pointer'}}>Add</button>
            </div>
            {world[wtab].length===0
              ?<div style={{fontSize:'0.65rem',color:'#3a2a5a',padding:'1rem 0',fontStyle:'italic'}}>Nothing added yet. Build your world.</div>
              :world[wtab].map((item,i)=>(
                <div key={i} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'0.5rem 0',borderBottom:'0.5px solid #1a1228',fontSize:'0.68rem',color:'#b8a8d4'}}>
                  <span>{item}</span>
                  <button onClick={()=>delW(wtab,i)} style={{background:'transparent',border:'none',color:'#3a2a5a',cursor:'pointer',fontSize:'0.85rem',padding:'0 0.3rem'}}><i className="ti ti-x"/></button>
                </div>
              ))
            }
          </div>
        )}
      </div>

      <div className="bottomnav">
        {TABS.map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} className={`navbtn${tab===t.id?' active':''}`}>
            <i className={`ti ${t.icon}`} style={{fontSize:20}}/>
            <span>{t.label}</span>
          </button>
        ))}
      </div>
    </div>
  );
}
