import React, { useState, useCallback, useEffect } from 'react';
import { Chessboard } from 'react-chessboard';
import { Chess } from 'chess.js';
import TutorBox from './TutorBox';
import { getBestMove, getTopMoves, evaluateMove } from '../engine/chessAI';
import { getTutorComment } from '../engine/tutor';

const LEVEL_NAMES = [
  'Absolute Beginner', 'Beginner (100)', 'Casual (300)', 'Novice (500)',
  'Improving (800)', 'Club Player (1000)', 'Solid (1200)', 'Tactician (1400)',
  'Positional (1600)', 'Advanced (1800)', 'Expert (2000)', 'Candidate Master (2200)',
  'International Master (2400)', 'Grandmaster (2600)', 'Maximum Strength',
];

const MODES = [
  { id: 'beginner', label: 'Beginner', desc: 'Learn piece movement with full explanations' },
  { id: 'learning', label: 'Learning', desc: 'AI explains after important moves' },
  { id: 'coach', label: 'Coach', desc: 'AI asks questions, you find answers' },
  { id: 'free', label: 'Free Play', desc: 'Normal chess with adjustable AI strength' },
];

const QUALITY_COLORS = {
  brilliant: '#f0c060', best: '#7ecfc0', excellent: '#7ecfc0',
  good: '#8ab8e8', interesting: '#b8a8d4', inaccuracy: '#f0c060',
  mistake: '#e09070', blunder: '#e07070',
};

export default function ChessGame() {
  const [game, setGame] = useState(new Chess());
  const [comment, setComment] = useState({
    tone: 'info', label: 'Welcome, Lithe',
    text: "You play as white — white always goes first. Select a mode below, then tap a piece to start. Green dots show where your piece can move.",
    tip: "Opening tip: Start by moving your center pawns — e2→e4 or d2→d4. This controls the center and opens lines for your bishops.",
    emoji: '👑',
  });
  const [level, setLevel] = useState(3);
  const [mode, setMode] = useState('learning');
  const [isThinking, setIsThinking] = useState(false);
  const [moveNumber, setMoveNumber] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [moveLog, setMoveLog] = useState([]);
  const [selectedPiece, setSelectedPiece] = useState(null);
  const [lastMoveFrom, setLastMoveFrom] = useState(null);
  const [lastMoveTo, setLastMoveTo] = useState(null);
  const [stats, setStats] = useState({ excellent: 0, good: 0, inaccuracy: 0, mistake: 0, blunder: 0, total: 0 });
  const [showLevelPicker, setShowLevelPicker] = useState(false);

  const makeAIMove = useCallback((currentGame) => {
    setIsThinking(true);
    setTimeout(() => {
      const prevFen = currentGame.fen();
      const aiMove = getBestMove(prevFen, level);
      if (!aiMove) { setIsThinking(false); return; }

      const newGame = new Chess(currentGame.fen());
      const move = newGame.move({ from: aiMove.from, to: aiMove.to, promotion: 'q' });
      if (!move) { setIsThinking(false); return; }

      setLastMoveFrom(aiMove.from);
      setLastMoveTo(aiMove.to);
      setGame(newGame);
      setMoveNumber(n => n + 1);

      const isCheckmate = newGame.isCheckmate();
      const isCheck = newGame.inCheck();

      const c = getTutorComment({
        move, prevFen, fen: newGame.fen(),
        isAI: true, quality: null,
        moveNumber: moveNumber + 1,
        isCheck, isCheckmate, isCoachMode: mode === 'coach',
      });
      setComment(c);

      setMoveLog(log => [...log, { san: move.san, color: 'b', moveNum: moveNumber + 1 }]);

      if (isCheckmate || newGame.isDraw()) setGameOver(true);
      setIsThinking(false);
    }, 500);
  }, [level, mode, moveNumber]);

  function onDrop(sourceSquare, targetSquare) {
    if (gameOver || isThinking || game.turn() !== 'w') return false;

    const prevFen = game.fen();
    const newGame = new Chess(game.fen());

    let move;
    try {
      move = newGame.move({ from: sourceSquare, to: targetSquare, promotion: 'q' });
    } catch {
      return false;
    }
    if (!move) return false;

    setLastMoveFrom(sourceSquare);
    setLastMoveTo(targetSquare);
    setGame(newGame);

    const newMoveNum = moveNumber + 1;
    setMoveNumber(newMoveNum);

    const isCheckmate = newGame.isCheckmate();
    const isCheck = newGame.inCheck();

    const evalResult = evaluateMove(prevFen, move, newGame.fen());
    setStats(s => ({
      ...s,
      total: s.total + 1,
      [evalResult.quality]: (s[evalResult.quality] || 0) + 1,
    }));

    const c = getTutorComment({
      move, prevFen, fen: newGame.fen(),
      isAI: false, quality: evalResult.quality,
      moveNumber: newMoveNum, isCheck, isCheckmate,
      isCoachMode: mode === 'coach',
    });
    setComment(c);
    setMoveLog(log => [...log, { san: move.san, color: 'w', quality: evalResult.quality, moveNum: newMoveNum }]);

    if (isCheckmate || newGame.isDraw()) {
      setGameOver(true);
      return true;
    }

    if (mode !== 'beginner' || Math.random() > 0.3) {
      setTimeout(() => makeAIMove(newGame), 300);
    }
    return true;
  }

  function handleHint(level) {
    const chess = new Chess(game.fen());
    const moves = chess.moves({ verbose: true });
    if (!moves.length) return null;

    if (level === 1) {
      const strategic = [
        'Think about king safety — is your king well protected?',
        'Look for undefended pieces on both sides of the board.',
        'Consider developing a piece that hasn\'t moved yet.',
        'Is there a way to control more of the center?',
        'Check if any of your pieces are under attack right now.',
      ];
      return { level: 1, text: strategic[Math.floor(Math.random() * strategic.length)] };
    }
    if (level === 2) {
      const captures = moves.filter(m => m.captured);
      if (captures.length) return { level: 2, text: `There's a capture available — consider your ${captures[0].piece === 'p' ? 'pawn' : captures[0].piece.toUpperCase()} on ${captures[0].from}.` };
      const checks = moves.filter(m => m.san.includes('+'));
      if (checks.length) return { level: 2, text: 'You have a check available. Look for the move that puts the king in check.' };
      return { level: 2, text: `Try developing your least-active piece toward the center.` };
    }
    if (level === 3) {
      const top = getTopMoves(game.fen(), 1);
      if (top[0]) return { level: 3, text: `Best move: ${top[0].san} — move your ${top[0].piece === 'p' ? 'pawn' : top[0].piece.toUpperCase()} from ${top[0].from} to ${top[0].to}.` };
    }
    return null;
  }

  function handleSuggest() {
    const top = getTopMoves(game.fen(), 3);
    if (!top.length) return;
    const names = { p: 'Pawn', n: 'Knight', b: 'Bishop', r: 'Rook', q: 'Queen', k: 'King' };
    setComment({
      tone: 'info2', label: 'Top 3 candidate moves', emoji: '🎯',
      text: top.map((m, i) => `${i + 1}. ${m.san} — ${names[m.piece] || 'Piece'} ${m.from}→${m.to}${m.captured ? ` captures ${names[m.captured]}` : ''}`).join('\n'),
      tip: 'These are strong moves but chess has many valid paths. Use your own judgment.',
    });
  }

  function resetGame() {
    setGame(new Chess());
    setGameOver(false);
    setMoveNumber(0);
    setMoveLog([]);
    setLastMoveFrom(null);
    setLastMoveTo(null);
    setStats({ excellent: 0, good: 0, inaccuracy: 0, mistake: 0, blunder: 0, total: 0 });
    setComment({
      tone: 'info', label: 'New game',
      text: `${MODES.find(m => m.id === mode)?.desc || ''}. You play as white. Make your first move.`,
      tip: 'Start with e4 or d4 — the two strongest opening moves in chess.',
      emoji: '♟',
    });
  }

  function undoMove() {
    const newGame = new Chess(game.fen());
    newGame.undo(); // undo AI
    newGame.undo(); // undo player
    setGame(newGame);
    setMoveNumber(n => Math.max(0, n - 2));
    setMoveLog(log => log.slice(0, -2));
    setGameOver(false);
    setComment({
      tone: 'info', label: 'Undone',
      text: 'Two moves undone. Think about what you could do differently.',
      tip: 'Every mistake is a lesson. Strong players replay positions to understand where they went wrong.',
      emoji: '↩',
    });
  }

  const customSquareStyles = {};
  if (lastMoveFrom) customSquareStyles[lastMoveFrom] = { backgroundColor: '#2a1a4088' };
  if (lastMoveTo) customSquareStyles[lastMoveTo] = { backgroundColor: '#3a2a6088' };

  const accuracy = stats.total > 0
    ? Math.round(((stats.excellent + stats.good + (stats.total - stats.excellent - stats.good - stats.inaccuracy - stats.mistake - stats.blunder)) / stats.total) * 100)
    : 100;

  return (
    <div style={{ fontFamily: "'IBM Plex Mono', monospace", color: '#b8a8d4', padding: '1rem' }}>
      {/* Mode selector */}
      <div style={{ marginBottom: '0.75rem' }}>
        <div style={{ fontSize: '0.5rem', color: '#4a3a6a', letterSpacing: '0.25em', textTransform: 'uppercase', marginBottom: '0.4rem' }}>Game mode</div>
        <div style={{ display: 'flex', gap: '0.3rem', flexWrap: 'wrap' }}>
          {MODES.map(m => (
            <button key={m.id} onClick={() => { setMode(m.id); resetGame(); }} style={{
              background: mode === m.id ? '#1a1228' : '#0e0c18',
              border: `0.5px solid ${mode === m.id ? '#7b3fff' : '#2a1e42'}`,
              color: mode === m.id ? '#d0b0ff' : '#4a3a6a',
              fontFamily: 'inherit', fontSize: '0.55rem', padding: '0.3rem 0.6rem',
              borderRadius: '4px', cursor: 'pointer', letterSpacing: '0.08em',
            }}>{m.label}</button>
          ))}
        </div>
      </div>

      {/* Level picker */}
      <div style={{ marginBottom: '0.75rem' }}>
        <button onClick={() => setShowLevelPicker(p => !p)} style={{
          background: '#0e0c18', border: '0.5px solid #3a2a5a',
          color: '#b8a8d4', fontFamily: 'inherit', fontSize: '0.6rem',
          padding: '0.35rem 0.75rem', borderRadius: '4px', cursor: 'pointer', width: '100%',
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        }}>
          <span><i className="ti ti-cpu" style={{ fontSize: '12px', marginRight: '6px' }} />AI: Level {level + 1} — {LEVEL_NAMES[level]}</span>
          <i className={`ti ${showLevelPicker ? 'ti-chevron-up' : 'ti-chevron-down'}`} style={{ fontSize: '12px' }} />
        </button>
        {showLevelPicker && (
          <div style={{ background: '#0d0b16', border: '0.5px solid #2a1e42', borderRadius: '4px', marginTop: '0.25rem', padding: '0.5rem', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.25rem' }}>
            {LEVEL_NAMES.map((name, i) => (
              <button key={i} onClick={() => { setLevel(i); setShowLevelPicker(false); resetGame(); }} style={{
                background: level === i ? '#1a1228' : 'transparent',
                border: `0.5px solid ${level === i ? '#7b3fff' : '#2a1e42'}`,
                color: level === i ? '#d0b0ff' : '#5a4a8a',
                fontFamily: 'inherit', fontSize: '0.52rem', padding: '0.3rem 0.4rem',
                borderRadius: '3px', cursor: 'pointer', textAlign: 'left',
              }}>Lv{i + 1} {name.split(' ')[0]}</button>
            ))}
          </div>
        )}
      </div>

      {/* Stats row */}
      {stats.total > 0 && (
        <div style={{ display: 'flex', gap: '0.4rem', marginBottom: '0.75rem', fontSize: '0.55rem' }}>
          <div style={{ background: '#0e0c18', border: '0.5px solid #2a1e42', borderRadius: '4px', padding: '0.3rem 0.5rem', flex: 1, textAlign: 'center' }}>
            <div style={{ color: '#7ecfc0' }}>{accuracy}%</div>
            <div style={{ color: '#3a2a5a', marginTop: '1px' }}>accuracy</div>
          </div>
          {stats.blunder > 0 && <div style={{ background: '#1a0808', border: '0.5px solid #5a2a2a', borderRadius: '4px', padding: '0.3rem 0.5rem', flex: 1, textAlign: 'center' }}>
            <div style={{ color: '#e07070' }}>{stats.blunder}</div>
            <div style={{ color: '#5a2a2a', marginTop: '1px' }}>blunders</div>
          </div>}
          {stats.mistake > 0 && <div style={{ background: '#1a0a08', border: '0.5px solid #5a3020', borderRadius: '4px', padding: '0.3rem 0.5rem', flex: 1, textAlign: 'center' }}>
            <div style={{ color: '#e09070' }}>{stats.mistake}</div>
            <div style={{ color: '#5a3020', marginTop: '1px' }}>mistakes</div>
          </div>}
          <div style={{ background: '#0a1a12', border: '0.5px solid #2a5a3a', borderRadius: '4px', padding: '0.3rem 0.5rem', flex: 1, textAlign: 'center' }}>
            <div style={{ color: '#7ecfc0' }}>{stats.excellent + stats.good}</div>
            <div style={{ color: '#2a5a3a', marginTop: '1px' }}>good moves</div>
          </div>
        </div>
      )}

      {/* Turn indicator */}
      <div style={{
        fontSize: '0.6rem', padding: '0.3rem 0.7rem', borderRadius: '3px', marginBottom: '0.5rem',
        display: 'inline-block',
        background: game.turn() === 'w' ? '#1e1530' : '#0e0c18',
        border: `0.5px solid ${game.turn() === 'w' ? '#3a2a5a' : '#2a1e42'}`,
        color: game.turn() === 'w' ? '#d0b0ff' : '#7a5a9a',
      }}>
        {isThinking ? '🤖 Computer thinking...' : gameOver ? '🏁 Game over' : game.turn() === 'w' ? '⬜ Your turn (white)' : '⬛ Computer\'s turn (black)'}
      </div>

      {/* Board */}
      <div style={{ borderRadius: '6px', overflow: 'hidden', border: '1px solid #2a1e42', marginBottom: '0.75rem' }}>
        <Chessboard
          position={game.fen()}
          onPieceDrop={onDrop}
          boardOrientation="white"
          customDarkSquareStyle={{ backgroundColor: '#1e1530' }}
          customLightSquareStyle={{ backgroundColor: '#2a2040' }}
          customSquareStyles={customSquareStyles}
          areArrowsAllowed={true}
          animationDuration={200}
        />
      </div>

      {/* Tutor box */}
      <TutorBox
        comment={comment}
        onHint={handleHint}
        onSuggest={handleSuggest}
        moveNumber={moveNumber}
      />

      {/* Controls */}
      <div style={{ display: 'flex', gap: '0.4rem', marginTop: '0.5rem', flexWrap: 'wrap' }}>
        <button onClick={resetGame} style={btnStyle}>
          <i className="ti ti-refresh" style={{ fontSize: '13px' }} /> New game
        </button>
        <button onClick={undoMove} style={btnStyle} disabled={moveNumber < 2}>
          <i className="ti ti-arrow-back-up" style={{ fontSize: '13px' }} /> Undo
        </button>
      </div>

      {/* Move log */}
      {moveLog.length > 0 && (
        <div style={{ marginTop: '0.75rem', background: '#0a0814', border: '0.5px solid #1e1530', borderRadius: '4px', padding: '0.5rem 0.65rem', maxHeight: '80px', overflowY: 'auto' }}>
          <div style={{ fontSize: '0.5rem', color: '#3a2a5a', letterSpacing: '0.2em', textTransform: 'uppercase', marginBottom: '0.35rem' }}>Move history</div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.25rem' }}>
            {moveLog.map((m, i) => (
              <span key={i} style={{
                fontSize: '0.6rem',
                color: m.color === 'w' ? (QUALITY_COLORS[m.quality] || '#b8a8d4') : '#7a5a9a',
                background: '#0d0b16', padding: '0.1rem 0.35rem', borderRadius: '2px',
              }}>
                {m.color === 'w' ? `${Math.ceil(m.moveNum / 2)}.` : ''}{m.san}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const btnStyle = {
  background: '#1a1228', border: '0.5px solid #3a2a5a', color: '#b8a8d4',
  fontFamily: "'IBM Plex Mono', monospace", fontSize: '0.58rem',
  letterSpacing: '0.08em', padding: '0.38rem 0.75rem', borderRadius: '4px',
  cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.35rem',
};
