import React, { useState } from 'react';

const TONE_STYLES = {
  brilliant: { border: '#c0a000', bg: '#1a1500', label: '#f0c060', icon: 'ti-sparkles' },
  best:      { border: '#2a7a4a', bg: '#0a1a12', label: '#7ecfc0', icon: 'ti-star' },
  excellent: { border: '#2a7a4a', bg: '#0a1a12', label: '#7ecfc0', icon: 'ti-check' },
  good:      { border: '#2a5a8a', bg: '#0a1218', label: '#8ab8e8', icon: 'ti-thumb-up' },
  interesting:{ border: '#5a4a8a', bg: '#0e0c18', label: '#b8a8d4', icon: 'ti-question-mark' },
  inaccuracy:{ border: '#8a6a10', bg: '#1a1208', label: '#f0c060', icon: 'ti-alert-circle' },
  mistake:   { border: '#8a3020', bg: '#1a0a08', label: '#e09070', icon: 'ti-x' },
  blunder:   { border: '#9a2020', bg: '#1a0808', label: '#e07070', icon: 'ti-flame' },
  ai:        { border: '#5a2fa0', bg: '#0d0b1a', label: '#a07ad0', icon: 'ti-robot' },
  warn:      { border: '#9a4020', bg: '#1a0e08', label: '#e08060', icon: 'ti-alert-triangle' },
  info:      { border: '#3a2a5a', bg: '#0d0b16', label: '#8a7aaa', icon: 'ti-school' },
  info2:     { border: '#3a2a5a', bg: '#0d0b16', label: '#8a7aaa', icon: 'ti-info-circle' },
};

export default function TutorBox({ comment, onHint, onSuggest, moveNumber }) {
  const [hintLevel, setHintLevel] = useState(0);
  const [hint, setHint] = useState(null);

  if (!comment) return null;
  const style = TONE_STYLES[comment.tone] || TONE_STYLES.info;

  const handleHint = (level) => {
    setHintLevel(level);
    if (onHint) {
      const h = onHint(level);
      setHint(h);
    }
  };

  const qualityColor = {
    brilliant: '#f0c060', best: '#7ecfc0', excellent: '#7ecfc0',
    good: '#8ab8e8', interesting: '#b8a8d4', inaccuracy: '#f0c060',
    mistake: '#e09070', blunder: '#e07070', ai: '#a07ad0',
  }[comment.tone] || '#b8a8d4';

  return (
    <div style={{ margin: '0.75rem 0', fontFamily: "'IBM Plex Mono', monospace" }}>
      <div style={{
        background: style.bg,
        border: `0.5px solid ${style.border}`,
        borderRadius: '6px',
        padding: '0.75rem 0.85rem',
        transition: 'border-color 0.3s',
      }}>
        {/* Label row */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.45rem', marginBottom: '0.5rem' }}>
          <i className={`ti ${style.icon}`} style={{ fontSize: '13px', color: style.label }} />
          <span style={{ fontSize: '0.58rem', color: style.label, letterSpacing: '0.15em', textTransform: 'uppercase', fontWeight: 500 }}>
            {comment.emoji && <span style={{ marginRight: '4px' }}>{comment.emoji}</span>}
            {comment.label}
          </span>
          {moveNumber && (
            <span style={{ marginLeft: 'auto', fontSize: '0.52rem', color: '#3a2a5a' }}>move {moveNumber}</span>
          )}
        </div>

        {/* Main text */}
        <p style={{ fontSize: '0.72rem', color: '#c0a8e8', lineHeight: 1.8, marginBottom: comment.tip ? '0.5rem' : 0 }}>
          {comment.text}
        </p>

        {/* Tip */}
        {comment.tip && (
          <div style={{
            fontSize: '0.62rem', color: '#7a5a9a', marginTop: '0.45rem',
            fontStyle: 'italic', lineHeight: 1.65,
            borderTop: '0.5px solid #1e1530', paddingTop: '0.45rem',
            display: 'flex', gap: '0.4rem', alignItems: 'flex-start',
          }}>
            <i className="ti ti-bulb" style={{ fontSize: '11px', color: '#5a3a8a', flexShrink: 0, marginTop: '2px' }} />
            {comment.tip}
          </div>
        )}

        {/* Hint shown */}
        {hint && (
          <div style={{
            marginTop: '0.5rem', padding: '0.5rem 0.65rem',
            background: '#0a0814', border: '0.5px solid #3a2a5a',
            borderRadius: '4px', fontSize: '0.68rem', color: '#d0b0ff', lineHeight: 1.7,
          }}>
            <span style={{ fontSize: '0.5rem', color: '#5a2fa0', textTransform: 'uppercase', letterSpacing: '0.15em', display: 'block', marginBottom: '0.25rem' }}>
              Hint level {hint.level}
            </span>
            {hint.text}
          </div>
        )}
      </div>

      {/* Action buttons */}
      <div style={{ display: 'flex', gap: '0.35rem', marginTop: '0.5rem', flexWrap: 'wrap' }}>
        <button onClick={() => handleHint(1)} style={btnStyle('#1a1228', '#2a1e42', '#7a5a9a')}>
          <i className="ti ti-eye" style={{ fontSize: '12px' }} /> Hint 1
        </button>
        <button onClick={() => handleHint(2)} style={btnStyle('#1a1228', '#3a2a5a', '#a07ad0')}>
          <i className="ti ti-eye-check" style={{ fontSize: '12px' }} /> Hint 2
        </button>
        <button onClick={() => handleHint(3)} style={btnStyle('#1a1228', '#5a2fa0', '#d0b0ff')}>
          <i className="ti ti-bulb" style={{ fontSize: '12px' }} /> Best move
        </button>
        {onSuggest && (
          <button onClick={onSuggest} style={{ ...btnStyle('#2a1a48', '#7b3fff', '#d0b0ff'), marginLeft: 'auto' }}>
            <i className="ti ti-chess" style={{ fontSize: '12px' }} /> Suggest
          </button>
        )}
      </div>
    </div>
  );
}

function btnStyle(bg, border, color) {
  return {
    background: bg, border: `0.5px solid ${border}`, color,
    fontFamily: "'IBM Plex Mono', monospace", fontSize: '0.58rem',
    letterSpacing: '0.08em', padding: '0.32rem 0.65rem',
    borderRadius: '4px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.3rem',
  };
}
