import React, { useState } from 'react';
import { PIECES_INFO, TACTICS, OPENINGS } from '../data/pieces';

const PIECE_SVG = {
  K: ({ color }) => (
    <svg viewBox="0 0 45 45" width="80" height="80">
      <g fill={color} stroke="#2a1e42" strokeWidth="1.5">
        <path d="M22.5 11.63V6M20 8h5" strokeLinecap="round"/>
        <path d="M11.5 37c5.5 3.5 15.5 3.5 21 0v-7s9-4.5 6-10.5c-4-6.5-13.5-3.5-16 4V11.63M11.5 30c5.5-3 15.5-3 21 0M11.5 33.5c5.5-3 15.5-3 21 0M11.5 37c5.5-3 15.5-3 21 0"/>
      </g>
    </svg>
  ),
  Q: ({ color }) => (
    <svg viewBox="0 0 45 45" width="80" height="80">
      <g fill={color} stroke="#2a1e42" strokeWidth="1.5">
        <circle cx="6" cy="12" r="2.75"/>
        <circle cx="14" cy="9" r="2.75"/>
        <circle cx="22.5" cy="8" r="2.75"/>
        <circle cx="31" cy="9" r="2.75"/>
        <circle cx="39" cy="12" r="2.75"/>
        <path d="M9 26c8.5-8.5 15.5-4 18 2C25 20 31 14.5 34.5 26l1.5 11H9z"/>
        <path d="M9 26c0 2 1.5 2 2.5 4 1 1.5 1 1 .5 3.5-1.5 1-1.5 2.5-1.5 2.5-1.5 1.5.5 2.5.5 2.5 6.5 1 16.5 1 23 0 0 0 1.5-1 0-2.5 0 0 .5-1.5-1-2.5-.5-2.5-.5-2 .5-3.5 1-2 2.5-2 2.5-4" strokeLinecap="round"/>
      </g>
    </svg>
  ),
  R: ({ color }) => (
    <svg viewBox="0 0 45 45" width="80" height="80">
      <g fill={color} stroke="#2a1e42" strokeWidth="1.5">
        <path d="M9 39h27v-3H9v3zM12 36v-4h21v4H12zM11 14V9h4v2h5V9h5v2h5V9h4v5" strokeLinecap="round"/>
        <path d="M34 14l-3 3H14l-3-3"/>
        <path d="M31 17v12.5H14V17"/>
        <path d="M31 29.5l1.5 2.5h-20l1.5-2.5"/>
        <path d="M11 14h23" fill="none"/>
      </g>
    </svg>
  ),
  B: ({ color }) => (
    <svg viewBox="0 0 45 45" width="80" height="80">
      <g fill={color} stroke="#2a1e42" strokeWidth="1.5">
        <path d="M9 36c3.39-.97 10.11.43 13.5-2 3.39 2.43 10.11 1.03 13.5 2 0 0 1.65.54 3 2-.68.97-1.65.99-3 .5-3.39-.97-10.11.46-13.5-1-3.39 1.46-10.11.03-13.5 1-1.354.49-2.323.47-3-.5 1.354-1.94 3-2 3-2z"/>
        <path d="M15 32c2.5 2.5 12.5 2.5 15 0 .5-1.5 0-2 0-2 0-2.5-2.5-4-2.5-4 5.5-1.5 6-11.5-5-15.5-11 4-10.5 14-5 15.5 0 0-2.5 1.5-2.5 4 0 0-.5.5 0 2z"/>
        <path d="M25 8a2.5 2.5 0 1 1-5 0 2.5 2.5 0 0 1 5 0z"/>
        <path d="M17.5 26h10M15 30h15" fill="none"/>
      </g>
    </svg>
  ),
  N: ({ color }) => (
    <svg viewBox="0 0 45 45" width="80" height="80">
      <g fill={color} stroke="#2a1e42" strokeWidth="1.5">
        <path d="M22 10c10.5 1 16.5 8 16 29H15c0-9 10-6.5 8-21"/>
        <path d="M24 18c.38 5.12-1.37 8.37-3.5 11-2.5 3.25-5.5 5.25-4.5 7.5-1-2.5 1-5 3.5-7.5 2.24-2.24 5.5-4.5 5-7-1-.5-2.5 1.5-3.5 1.5-1 0-3-.5-3-2.5 0-1.5 2.5-2.5 4.5-3.5 2-1 2.5-2 3-3.5"/>
        <path d="M9.5 25.5a.5.5 0 1 1-1 0 .5.5 0 0 1 1 0z" fill="#2a1e42"/>
        <path d="M14.933 15.75a.5 1.5 30 1 1-.866-.5.5 1.5 30 0 1 .866.5z" fill="#2a1e42"/>
      </g>
    </svg>
  ),
  P: ({ color }) => (
    <svg viewBox="0 0 45 45" width="80" height="80">
      <g fill={color} stroke="#2a1e42" strokeWidth="1.5">
        <path d="M22.5 9c-2.21 0-4 1.79-4 4 0 .89.29 1.71.78 2.38C17.33 16.5 16 18.59 16 21c0 2.03.94 3.84 2.41 5.03C15.41 27.09 11 31.58 11 39.5H34c0-7.42-4.41-12.41-7.41-13.47C28.06 24.84 29 23.03 29 21c0-2.41-1.33-4.5-3.28-5.62.49-.67.78-1.49.78-2.38 0-2.21-1.79-4-4-4z"/>
      </g>
    </svg>
  ),
};

const toneColors = {
  '#d0b0ff': { bg: '#1a0f2e', border: '#5a2fa0', text: '#d0b0ff' },
  '#f9a8c9': { bg: '#1e0f18', border: '#8a3060', text: '#f9a8c9' },
  '#7ecfc0': { bg: '#0a1a18', border: '#2a7a70', text: '#7ecfc0' },
  '#f0c060': { bg: '#1a1208', border: '#8a6a10', text: '#f0c060' },
  '#b8a8d4': { bg: '#12101a', border: '#4a3a7a', text: '#b8a8d4' },
  '#c07070': { bg: '#1a0a0a', border: '#7a3030', text: '#c07070' },
};

export default function PieceGuide() {
  const [activeTab, setActiveTab] = useState('pieces');
  const [selectedPiece, setSelectedPiece] = useState('K');
  const [expandedTactic, setExpandedTactic] = useState(null);

  const tabs = [
    { id: 'pieces', label: 'Pieces' },
    { id: 'tactics', label: 'Tactics' },
    { id: 'openings', label: 'Openings' },
  ];

  const pieceKeys = ['K', 'Q', 'R', 'B', 'N', 'P'];
  const info = PIECES_INFO[selectedPiece];
  const colors = toneColors[info.color] || toneColors['#b8a8d4'];
  const SvgPiece = PIECE_SVG[selectedPiece];

  return (
    <div style={{ padding: '1rem', fontFamily: "'IBM Plex Mono', monospace", color: '#b8a8d4' }}>
      {/* Tab bar */}
      <div style={{ display: 'flex', gap: '0.35rem', marginBottom: '1.25rem' }}>
        {tabs.map(t => (
          <button key={t.id} onClick={() => setActiveTab(t.id)} style={{
            flex: 1, background: activeTab === t.id ? '#1a1228' : 'transparent',
            border: activeTab === t.id ? '0.5px solid #7b3fff' : '0.5px solid #2a1e42',
            color: activeTab === t.id ? '#d0b0ff' : '#4a3a6a',
            fontFamily: 'inherit', fontSize: '0.58rem', letterSpacing: '0.1em',
            padding: '0.4rem 0.5rem', borderRadius: '4px', cursor: 'pointer', textTransform: 'uppercase',
          }}>{t.label}</button>
        ))}
      </div>

      {/* PIECES TAB */}
      {activeTab === 'pieces' && (
        <div>
          {/* Piece selector */}
          <div style={{ display: 'flex', gap: '0.4rem', marginBottom: '1rem' }}>
            {pieceKeys.map(k => {
              const pi = PIECES_INFO[k];
              const selected = k === selectedPiece;
              return (
                <button key={k} onClick={() => setSelectedPiece(k)} style={{
                  flex: 1, padding: '0.5rem 0.25rem', border: selected ? `1.5px solid ${pi.color}` : '0.5px solid #2a1e42',
                  borderRadius: '6px', background: selected ? toneColors[pi.color]?.bg || '#1a1228' : '#0e0c18',
                  cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '0.2rem',
                }}>
                  <span style={{ fontSize: '1.4rem', color: selected ? pi.color : '#4a3a6a' }}>{pi.symbol}</span>
                  <span style={{ fontSize: '0.48rem', color: selected ? pi.color : '#3a2a5a', letterSpacing: '0.1em', textTransform: 'uppercase' }}>
                    {pi.name.slice(0, 3)}
                  </span>
                </button>
              );
            })}
          </div>

          {/* Piece detail card */}
          <div style={{ background: colors.bg, border: `0.5px solid ${colors.border}`, borderRadius: '8px', padding: '1rem', marginBottom: '0.75rem' }}>
            {/* Header */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '0.85rem' }}>
              <div style={{ background: '#0a0814', borderRadius: '8px', padding: '0.5rem', border: `0.5px solid ${colors.border}` }}>
                {SvgPiece && <SvgPiece color={info.color} />}
              </div>
              <div>
                <div style={{ fontSize: '1.2rem', fontWeight: 500, color: colors.text, fontFamily: "'Cinzel', serif" }}>{info.name}</div>
                <div style={{ fontSize: '0.58rem', color: '#5a4a8a', marginTop: '0.2rem' }}>Value: {info.value}</div>
                <div style={{ fontSize: '0.6rem', color: '#7a5a9a', marginTop: '0.1rem', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                  <i className="ti ti-arrows-move" style={{ fontSize: '12px' }} />
                  {info.movement}
                </div>
              </div>
            </div>

            {/* Description */}
            <p style={{ fontSize: '0.72rem', color: '#c0a8e8', lineHeight: 1.8, marginBottom: '0.75rem' }}>{info.description}</p>

            {/* Strengths & Weaknesses */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem', marginBottom: '0.75rem' }}>
              <div style={{ background: '#0a1a12', border: '0.5px solid #2a5a3a', borderRadius: '5px', padding: '0.6rem' }}>
                <div style={{ fontSize: '0.52rem', color: '#4a9a6a', letterSpacing: '0.2em', textTransform: 'uppercase', marginBottom: '0.4rem' }}>
                  <i className="ti ti-thumb-up" style={{ fontSize: '11px', marginRight: '4px' }} />Strengths
                </div>
                {info.strengths.map((s, i) => (
                  <div key={i} style={{ fontSize: '0.63rem', color: '#7ecfc0', marginBottom: '0.25rem', display: 'flex', gap: '0.35rem' }}>
                    <span style={{ color: '#4a9a6a', flexShrink: 0 }}>+</span>{s}
                  </div>
                ))}
              </div>
              <div style={{ background: '#1a0a0a', border: '0.5px solid #5a2a2a', borderRadius: '5px', padding: '0.6rem' }}>
                <div style={{ fontSize: '0.52rem', color: '#9a4a4a', letterSpacing: '0.2em', textTransform: 'uppercase', marginBottom: '0.4rem' }}>
                  <i className="ti ti-thumb-down" style={{ fontSize: '11px', marginRight: '4px' }} />Weaknesses
                </div>
                {info.weaknesses.map((w, i) => (
                  <div key={i} style={{ fontSize: '0.63rem', color: '#c07070', marginBottom: '0.25rem', display: 'flex', gap: '0.35rem' }}>
                    <span style={{ color: '#9a4a4a', flexShrink: 0 }}>−</span>{w}
                  </div>
                ))}
              </div>
            </div>

            {/* Tips */}
            <div style={{ background: '#0d0b1a', border: '0.5px solid #2a1e42', borderRadius: '5px', padding: '0.7rem', marginBottom: '0.65rem' }}>
              <div style={{ fontSize: '0.52rem', color: '#5a4a8a', letterSpacing: '0.2em', textTransform: 'uppercase', marginBottom: '0.5rem' }}>
                <i className="ti ti-bulb" style={{ fontSize: '11px', marginRight: '4px' }} />Pro tips
              </div>
              {info.tips.map((t, i) => (
                <div key={i} style={{ fontSize: '0.65rem', color: '#b8a8d4', marginBottom: '0.35rem', display: 'flex', gap: '0.4rem', lineHeight: 1.6 }}>
                  <span style={{ color: colors.text, flexShrink: 0 }}>{i + 1}.</span>{t}
                </div>
              ))}
            </div>

            {/* Fun fact */}
            <div style={{ background: '#0e0c18', borderLeft: `2px solid ${colors.border}`, paddingLeft: '0.75rem', paddingTop: '0.4rem', paddingBottom: '0.4rem' }}>
              <div style={{ fontSize: '0.52rem', color: '#4a3a6a', letterSpacing: '0.15em', textTransform: 'uppercase', marginBottom: '0.25rem' }}>
                <i className="ti ti-history" style={{ fontSize: '11px', marginRight: '4px' }} />Did you know
              </div>
              <p style={{ fontSize: '0.65rem', color: '#8a7aa8', lineHeight: 1.7, fontStyle: 'italic' }}>{info.funFact}</p>
            </div>
          </div>
        </div>
      )}

      {/* TACTICS TAB */}
      {activeTab === 'tactics' && (
        <div>
          <div style={{ fontSize: '0.6rem', color: '#5a4a8a', marginBottom: '1rem', lineHeight: 1.7 }}>
            Tactics are short sequences that win material or deliver checkmate. Learning these patterns is the fastest way to improve.
          </div>
          {TACTICS.map((t, i) => {
            const open = expandedTactic === i;
            const tc = toneColors[t.color] || toneColors['#b8a8d4'];
            return (
              <div key={i} style={{ background: tc.bg, border: `0.5px solid ${open ? tc.border : '#2a1e42'}`, borderRadius: '6px', marginBottom: '0.5rem', overflow: 'hidden' }}>
                <div onClick={() => setExpandedTactic(open ? null : i)} style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '0.75rem', cursor: 'pointer' }}>
                  <div style={{ width: '36px', height: '36px', background: '#0a0814', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0, border: `0.5px solid ${tc.border}` }}>
                    {t.icon}
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: '0.78rem', fontWeight: 500, color: tc.text }}>{t.name}</div>
                    <div style={{ fontSize: '0.6rem', color: '#5a4a8a', marginTop: '0.1rem' }}>{t.description.slice(0, 55)}...</div>
                  </div>
                  <i className={`ti ${open ? 'ti-chevron-up' : 'ti-chevron-down'}`} style={{ fontSize: '14px', color: '#4a3a6a' }} />
                </div>
                {open && (
                  <div style={{ padding: '0 0.75rem 0.75rem', borderTop: `0.5px solid ${tc.border}` }}>
                    <p style={{ fontSize: '0.7rem', color: '#c0a8e8', lineHeight: 1.8, marginTop: '0.65rem', marginBottom: '0.6rem' }}>{t.description}</p>
                    <div style={{ background: '#0a0814', border: `0.5px solid ${tc.border}`, borderRadius: '4px', padding: '0.6rem' }}>
                      <div style={{ fontSize: '0.5rem', color: '#4a3a6a', letterSpacing: '0.2em', textTransform: 'uppercase', marginBottom: '0.35rem' }}>Example</div>
                      <p style={{ fontSize: '0.65rem', color: '#b8a8d4', lineHeight: 1.7, fontStyle: 'italic' }}>{t.example}</p>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* OPENINGS TAB */}
      {activeTab === 'openings' && (
        <div>
          <div style={{ fontSize: '0.6rem', color: '#5a4a8a', marginBottom: '1rem', lineHeight: 1.7 }}>
            The opening sets the tone for the entire game. Learn a few solid openings and you'll start every game with confidence.
          </div>
          {OPENINGS.map((o, i) => {
            const tc = toneColors[o.color] || toneColors['#b8a8d4'];
            return (
              <div key={i} style={{ background: tc.bg, border: `0.5px solid ${tc.border}`, borderRadius: '6px', padding: '0.85rem', marginBottom: '0.6rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem' }}>
                  <div style={{ fontSize: '0.85rem', fontWeight: 500, color: tc.text }}>{o.name}</div>
                  <span style={{ fontSize: '0.5rem', background: '#0a0814', border: `0.5px solid ${tc.border}`, color: tc.text, padding: '0.15rem 0.45rem', borderRadius: '10px', letterSpacing: '0.1em', textTransform: 'uppercase', flexShrink: 0, marginLeft: '0.5rem' }}>{o.difficulty}</span>
                </div>
                <div style={{ fontSize: '0.62rem', color: '#7b3fff', fontFamily: 'monospace', marginBottom: '0.5rem', background: '#0a0814', padding: '0.3rem 0.5rem', borderRadius: '3px', display: 'inline-block' }}>
                  {o.moves}
                </div>
                <p style={{ fontSize: '0.67rem', color: '#b8a8d4', lineHeight: 1.75, marginBottom: '0.5rem' }}>{o.description}</p>
                <div style={{ fontSize: '0.6rem', color: '#7a5a9a', display: 'flex', gap: '0.35rem', alignItems: 'flex-start' }}>
                  <i className="ti ti-target" style={{ fontSize: '12px', flexShrink: 0, marginTop: '1px' }} />
                  <span style={{ lineHeight: 1.6 }}>{o.plan}</span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
